package com.jobradar.taxonomy.skill; import com.jobradar.taxonomy.common.TaxonomyEntity; import jakarta.persistence.*; @Entity @Table(name="skills") public class SkillEntity extends TaxonomyEntity {@Column(nullable=false,length=100) private String name;@Column(nullable=false,length=120) private String slug;protected SkillEntity(){}public SkillEntity(String n,String s){name=n;slug=s;}public String getName(){return name;}public String getSlug(){return slug;}public void update(String n,String s){name=n;slug=s;}}
